<?php
namespace CmuLms;
final class ExamController {
 public function open(\PDO $db):void{$u=Auth::role('student');$a=ModelAccess::one($db,'SELECT a.*,e.title,e.duration_minutes,e.allow_back_navigation FROM exam_attempts a JOIN exams e ON e.id=a.exam_id WHERE a.id=? AND a.student_id=?',[(int)$_GET['attempt'],$u['id']]);if(!$a)exit('Attempt not found.');if($a['status']!=='in_progress'){$_SESSION['error']='This attempt is already submitted.';Http::redirect('?route=dashboard');}$ids=json_decode($a['question_ids'],true)?:[];$qs=$ids?ModelAccess::all($db,'SELECT * FROM questions WHERE id IN ('.implode(',',array_fill(0,count($ids),'?')).')',array_map('intval',$ids)):[];$answers=[];foreach(ModelAccess::all($db,'SELECT question_id,answer FROM exam_answers WHERE attempt_id=?',[$a['id']]) as $x)$answers[$x['question_id']]=json_decode($x['answer'],true)[0]??'';View::render('exams/take',['user'=>$u,'attempt'=>$a,'questions'=>$qs,'answers'=>$answers]);}
 public function start(\PDO $db):never{$u=Auth::role('student');View::checkCsrf();$exam=ModelAccess::one($db,'SELECT e.* FROM exams e JOIN enrollments en ON en.course_id=e.course_id AND en.user_id=? AND en.status="active" WHERE e.id=?',[$u['id'],(int)$_POST['exam_id']]);if(!$exam)exit('Exam unavailable.');$active=ModelAccess::one($db,'SELECT * FROM exam_attempts WHERE exam_id=? AND student_id=? AND status="in_progress" ORDER BY id DESC LIMIT 1',[$exam['id'],$u['id']]);if(!$active){$used=(int)ModelAccess::one($db,'SELECT COUNT(*) c FROM exam_attempts WHERE exam_id=? AND student_id=?',[$exam['id'],$u['id']])['c'];if($used >= $exam['attempts_allowed']){$_SESSION['error']='No attempts remaining.';Http::redirect('?route=dashboard');}$qs=ModelAccess::all($db,'SELECT id FROM questions WHERE pool_id=? AND is_active=1 ORDER BY RAND() LIMIT '.max(1,(int)$exam['question_count']),[$exam['question_pool_id']]);$ids=json_encode(array_column($qs,'id'));$now=time();$ends=date('Y-m-d H:i:s',$now+$exam['duration_minutes']*60);$s=$db->prepare('INSERT INTO exam_attempts(exam_id,student_id,attempt_number,started_at,ends_at,consented_at,question_ids,option_order,status,ip_start,user_agent_start,created_at,updated_at) VALUES(?,?,?,?,?,NOW(),?,?,"in_progress",?,?,NOW(),NOW())');$s->execute([$exam['id'],$u['id'],$used+1,date('Y-m-d H:i:s',$now),$ends,$ids,json_encode([]),$_SERVER['REMOTE_ADDR']??null,$_SERVER['HTTP_USER_AGENT']??'']);$active=ModelAccess::one($db,'SELECT * FROM exam_attempts WHERE id=LAST_INSERT_ID()');}Http::redirect('?route=exam&attempt='.$active['id']);}
 public function answer(\PDO $db):never{$u=Auth::role('student');View::checkCsrf();$a=ModelAccess::one($db,'SELECT * FROM exam_attempts WHERE id=? AND student_id=? AND status="in_progress"',[(int)$_POST['attempt_id'],$u['id']]);if(!$a)exit('Attempt closed.');if(strtotime($a['ends_at'])<=time()){ModelAccess::query($db,'UPDATE exam_attempts SET status="auto_submitted",submitted_at=NOW() WHERE id=?',[$a['id']]);exit('Time expired.');}ModelAccess::query($db,'INSERT INTO exam_answers(attempt_id,question_id,answer,answered_at,created_at,updated_at) VALUES(?,?,?,NOW(),NOW(),NOW()) ON DUPLICATE KEY UPDATE answer=VALUES(answer),answered_at=NOW(),updated_at=NOW()',[$a['id'],(int)$_POST['question_id'],json_encode([$_POST['answer']??''])]);Http::redirect('?route=exam&attempt='.$a['id']);}
 public function submit(\PDO $db):never{$u=Auth::role('student');View::checkCsrf();$a=ModelAccess::one($db,'SELECT * FROM exam_attempts WHERE id=? AND student_id=? AND status="in_progress"',[(int)$_POST['attempt_id'],$u['id']]);if($a)ModelAccess::query($db,'UPDATE exam_attempts SET status="submitted",submitted_at=NOW(),honesty_confirmed=1,ip_submit=?,user_agent_submit=?,updated_at=NOW() WHERE id=?',[$_SERVER['REMOTE_ADDR']??null,$_SERVER['HTTP_USER_AGENT']??'',$a['id']]);$_SESSION['flash']='Exam submitted successfully.';Http::redirect('?route=dashboard');}
 public function create(\PDO $db):never{$u=Auth::role('teacher');View::checkCsrf();$s=$db->prepare('INSERT INTO exams(course_id,question_pool_id,title,duration_minutes,attempts_allowed,question_count,starts_at,ends_at,camera_required,allow_back_navigation,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,NOW(),NOW())');$s->execute([(int)$_POST['course_id'],(int)$_POST['question_pool_id'],trim($_POST['title']),max(1,(int)$_POST['duration_minutes']),max(1,(int)$_POST['attempts_allowed']),max(1,(int)$_POST['question_count']),$_POST['starts_at']?:null,$_POST['ends_at']?:null,!empty($_POST['camera_required']),!empty($_POST['allow_back_navigation'])]);$_SESSION['flash']='Exam posted successfully.';Http::redirect('?route=course&id='.(int)$_POST['course_id'].'&tab=activities');}
}
